export const EVENTS=Object.freeze([{id:"easy",label:"Easy",blurb:"Against the three slowest cars in the hall"},{id:"medium",label:"Medium",blurb:"Against three cars from the middle of the pack"},{id:"hard",label:"Hard",blurb:"Against the three fastest, last year’s champion among them"},{id:"trial",label:"Time Trial",blurb:"Your own cars against each other, or one alone"}]),UI=Object.freeze({title:"DERBY DAY",subtitle:"Race a wooden derby car down a four-lane track",raceLegend:"Your race",carLegend:"Your car",carsLegend:"Your cars, up to four",go:"Go!",pickOne:"Please pick at least one car for the Time Trial.",tooMany:"The track has four lanes, so four cars at most.",skip:"Skip to results",you:"You",replay:"Photo finish",resultsTitle:"Results",raceAgain:"Race again",another:"Choose another race",lanesHeading:"Each lane’s average",whyHeading:"Why your car ran as it did",trialHeading:"How your cars compared",place:"Place",car:"Car",average:"Average",heats:"Heats",seconds:"seconds"});export function eventLabel(e){const t=EVENTS.find(r=>r.id===e);return t?e==="trial"?t.label:`${t.label} division`:""}export function clock(e){return e.toFixed(3)}export function placeWord(e){const t=e%100;return t>=11&&t<=13?`${e}th`:`${e}${["th","st","nd","rd"][e%10]||"th"}`}export function heatOf(e,t){return`Heat ${e} of ${t}`}export function staging(e,t){return e===1?"Cars on the track. Lane 4 runs a hair slow, so every car will race in every lane.":e===t?"The last heat. One more lane each.":`Heat ${e}. Every car moves over one lane.`}export const OFF="And they’re off!";export function heatWinner(e,t,r){return`${t} takes heat ${e} in ${clock(r)} seconds.`}export function heatSpoken(e,t){const r=t.map(n=>`${n.name} ${placeWord(n.place)}, ${clock(n.time)} seconds`);return`Heat ${e}: ${r.join(". ")}.`}export function resultsSpoken(e,t){const r=t.map(n=>`${placeWord(n.place)}, ${n.name}, averaging ${clock(n.average)} seconds`);return`${eventLabel(e)} results. ${r.join(". ")}.`}const o=e=>`${clock(e)} seconds`,c=5e-4;export function whyLines(e,t,r){const n=e.lines.filter(a=>a.saved!==null&&a.saved>c).sort((a,l)=>l.saved-a.saved),i=e.lines.filter(a=>a.more>c).sort((a,l)=>l.more-a.more),s=[],h={weight:a=>`Its extra weight was worth ${o(a)} over the kit’s own weight.`,balance:a=>`Weight toward the back was worth ${o(a)} over a car balanced in the middle.`,axles:a=>`The work on its axles was worth ${o(a)}.`,alignment:a=>`Straight wheels were worth ${o(a)}.`,shape:a=>`Its shape was worth ${o(a)} over a plain block.`},u=t.balance>r,d={weight:a=>`Weights up to the full 5 ounces would save ${o(a)}.`,balance:a=>u?`Moving the weight back, to about three quarters of an inch in front of the rear axle, would save ${o(a)}.`:`Moving the weight forward a little, to about three quarters of an inch in front of the rear axle, would save ${o(a)}.`,axles:a=>`Polished axles and graphite would save ${o(a)}.`,alignment:a=>`Aligning the wheels would save ${o(a)}.`,shape:a=>`A slimmer shape would save ${o(a)}.`};n.length&&s.push(h[n[0].id](n[0].saved));for(const a of i.slice(0,2))s.push(d[a.id](a.more));return(!i.length||i[0].more<.002)&&s.push("There is very little left to find. This car is about as fast as the rules allow."),s}export function trialLines(e){if(e.length===1)return[`${e[0].name} averaged ${o(e[0].average)} over the four lanes.`];const t=[];for(let r=1;r<e.length;r++){const n=e[r].average-e[r-1].average;t.push(n>c?`${e[r-1].name} beat ${e[r].name} by ${o(n)}.`:`${e[r-1].name} and ${e[r].name} tied.`)}return t}
